script:
const GREY = "#cfd8da", RED = "#c0392b", TEAL = "#2a9d8f", ACC = "#e76f51", INK = "#16323a", MUTED = "#5f7a80";
const COLS = [84, 130, 176, 222, 268], ROWS = [192, 235, 278, 321], S = 0.85;
const XS = [120, 296, 440], LY = 450;
const MX = 548, MW = 28, MTOP = 386, MBOT = 494;
let E = {};
const F = "system-ui,sans-serif";
function txt(api, parent, s, a) {
  const t = api.el("text", Object.assign({"font-family": F, "text-anchor": "middle", "dominant-baseline": "central"}, a), parent);
  t.textContent = s; return t;
}
function setup(api) {
  const grid = api.$("#grid"), stats = api.$("#stats"), tl = api.$("#timeline"), fx = api.$("#fx");
  E.people = [];
  for (let r = 0; r < 4; r++) for (let c = 0; c < 5; c++) {
    const u = api.el("use", {href: "#person", x: -16, y: -22, width: 32, height: 44, fill: GREY,
      transform: "translate(" + COLS[c] + " " + ROWS[r] + ") scale(" + S + ")"}, grid);
    E.people.push({u: u, x: COLS[c], y: ROWS[r]});
  }
  E.rings = [0, 1].map(i => api.el("circle", {cx: COLS[i], cy: ROWS[0] - 1, r: 22, fill: "none", stroke: INK,
    "stroke-width": 2.4, "stroke-dasharray": "5 4", opacity: 0}, grid));
  // statistics
  E.big = txt(api, stats, "≈ 25%", {x: 455, y: 206, fill: RED, "font-size": 46, "font-weight": 800, opacity: 0});
  E.week = txt(api, stats, "at 1 week", {x: 455, y: 245, fill: RED, "font-size": 19, "font-weight": 700, opacity: 0});
  E.div = api.el("line", {x1: 380, y1: 272, x2: 530, y2: 272, stroke: "#e3ecec", "stroke-width": 2, opacity: 0}, stats);
  E.m3 = api.el("g", {opacity: 0}, stats);
  api.el("circle", {cx: 366, cy: 302, r: 9, fill: "none", stroke: INK, "stroke-width": 2, "stroke-dasharray": "4 3"}, E.m3);
  txt(api, E.m3, "≈ 10% at 3 months", {x: 384, y: 302, fill: MUTED, "font-size": 18, "font-weight": 700, "text-anchor": "start"});
  // timeline
  E.prog = api.el("path", {d: "M 120 450 L 120 450", stroke: "#3d5a62", "stroke-width": 6, "stroke-linecap": "round", fill: "none", opacity: 0}, tl);
  E.arc = api.el("path", {d: "M 126 437 Q 208 390 290 437", stroke: MUTED, "stroke-width": 2.2, fill: "none", "stroke-linecap": "round", pathLength: 1, "stroke-dasharray": "0 1"}, tl);
  E.arcHead = api.el("path", {d: "M 280 428 L 290 437 L 277 439", stroke: MUTED, "stroke-width": 2.2, fill: "none", "stroke-linecap": "round", "stroke-linejoin": "round", opacity: 0}, tl);
  E.head2 = api.el("path", {d: "M 512 441 L 524 450 L 512 459", stroke: "#3d5a62", "stroke-width": 6, "stroke-linecap": "round", "stroke-linejoin": "round", fill: "none", opacity: 0}, tl);
  E.arcLabel = txt(api, tl, "48 h", {x: 208, y: 398, fill: MUTED, "font-size": 17, "font-weight": 700, opacity: 0});
  E.pill = api.el("rect", {x: 216, y: 466, width: 160, height: 54, rx: 14, fill: "#fdeee9", stroke: "#f5c3b3", "stroke-width": 1.5, opacity: 0}, tl);
  E.pulse = api.el("circle", {cx: XS[1], cy: LY, r: 10, fill: "none", stroke: ACC, "stroke-width": 3, opacity: 0}, tl);
  const cols = [INK, ACC, RED];
  E.dots = XS.map((x, i) => api.el("circle", {cx: x, cy: LY, r: 10, fill: cols[i], stroke: "#ffffff", "stroke-width": 3, opacity: 0}, tl));
  const top = [["Day 0", "theatre: fixation"], ["Day 2", "back to theatre"], ["Evening", "confused"]];
  E.labels = top.map((p, i) => {
    const g = api.el("g", {opacity: 0}, tl);
    txt(api, g, p[0], {x: XS[i], y: 482, fill: cols[i], "font-size": 18, "font-weight": 800});
    txt(api, g, p[1], {x: XS[i], y: 504, fill: INK, "font-size": 17, "font-weight": 600});
    return g;
  });
  // confused-patient cue: small greyed brain with a question mark
  E.brain = api.$("#brain");
  E.cue = api.el("g", {opacity: 0}, fx);
  if (E.brain) { E.brain.parentNode.removeChild(E.brain); E.cue.appendChild(E.brain); api.set(E.brain, {filter: "url(#greyed)"}); }
  E.q = api.el("g", {opacity: 0}, fx);
  api.el("circle", {cx: 474, cy: 384, r: 13, fill: RED, stroke: "#ffffff", "stroke-width": 2.5}, E.q);
  txt(api, E.q, "?", {x: 474, y: 385, fill: "#ffffff", "font-size": 18, "font-weight": 800});
  E.fill = api.$("#meterFill"); E.risk = api.$("#riskLabel");

}
function pop(api, el, cx, cy, k) {
  const s = Math.max(0.001, k);
  api.set(el, {opacity: Math.min(1, k * 1.6), transform: "translate(" + cx + " " + cy + ") scale(" + s.toFixed(3) + ") translate(" + (-cx) + " " + (-cy) + ")"});
}
function fadeUp(api, el, k, dy) {
  api.set(el, {opacity: k, transform: "translate(0 " + ((1 - k) * dy).toFixed(2) + ")"});
}
function render(t, api) {
  // Beat 1: 5 of 20 people (about 1 in 4) fill red one by one.
  E.people.forEach((p, i) => {
    let k = 0, b = 0;
    if (i < 5) { k = api.seg(t, 200 + i * 230, 520 + i * 230, "ease_out"); b = Math.sin(Math.PI * k) * 0.2; }
    api.set(p.u, {fill: api.mixColor(GREY, RED, k), transform: "translate(" + p.x + " " + p.y + ") scale(" + (S * (1 + b)).toFixed(3) + ")"});
  });
  const kb = api.seg(t, 1000, 1450, "ease_out");
  api.set(E.big, {opacity: kb, transform: "translate(" + ((1 - kb) * 18).toFixed(2) + " 0)"});
  api.set(E.week, {opacity: kb, transform: "translate(" + ((1 - kb) * 18).toFixed(2) + " 0)"});
  api.set(E.div, {opacity: api.seg(t, 1500, 1800)});
  const k10 = api.seg(t, 1750, 2150, "ease_out");
  fadeUp(api, E.m3, k10, 10);
  E.rings.forEach((r, i) => pop(api, r, COLS[i], ROWS[0] - 1, api.seg(t, 1750 + i * 120, 2150 + i * 120, "back_out")));
  // Beat 2: day 0, then back to theatre 48 h later; risk climbs.
  pop(api, E.dots[0], XS[0], LY, api.seg(t, 2600, 2950, "back_out"));
  fadeUp(api, E.labels[0], api.seg(t, 2650, 3000, "ease_out"), 8);
  const a1 = api.seg(t, 2850, 3350, "ease_in_out"), a2 = api.seg(t, 5150, 5450, "ease_in_out"), a3 = api.seg(t, 5500, 5900, "ease_in_out");
  let x = XS[0] + (XS[1] - XS[0]) * a1 + (XS[2] - XS[1]) * a2 + (514 - XS[2]) * a3;
  api.set(E.prog, {d: "M 120 450 L " + x.toFixed(1) + " 450", opacity: t >= 2850 ? 1 : 0});
  const ka = api.seg(t, 2850, 3350, "ease_in_out");
  api.set(E.arc, {"stroke-dasharray": ka.toFixed(4) + " 1", opacity: ka > 0 ? 1 : 0});
  api.set(E.head2, {opacity: api.seg(t, 5800, 5950)});
  api.set(E.arcHead, {opacity: api.seg(t, 3250, 3400)});
  fadeUp(api, E.arcLabel, api.seg(t, 3100, 3450, "ease_out"), 6);
  const kp = api.seg(t, 3300, 3650, "back_out");
  pop(api, E.pill, XS[1], 493, kp);
  pop(api, E.dots[1], XS[1], LY, kp);
  fadeUp(api, E.labels[1], api.seg(t, 3350, 3700, "ease_out"), 8);
  const pu = api.seg(t, 3500, 4300, "ease_out");
  api.set(E.pulse, {r: 10 + 20 * pu, opacity: pu > 0 && pu < 1 ? 0.7 * (1 - pu) : 0});
  // Beat 3: confused that evening; risk higher, meter turns red.
  pop(api, E.dots[2], XS[2], LY, api.seg(t, 5300, 5650, "back_out"));
  fadeUp(api, E.labels[2], api.seg(t, 5350, 5700, "ease_out"), 8);
  const kc = api.seg(t, 5350, 5900, "ease_out");
  pop(api, E.cue, 440, 405, 0.6 + 0.4 * kc); api.set(E.cue, {opacity: kc});
  pop(api, E.q, 474, 384, api.seg(t, 5850, 6200, "back_out"));
  const m1 = api.seg(t, 3700, 4700, "ease_in_out"), m2 = api.seg(t, 5400, 6400, "ease_in_out");
  const f = 0.2 + (0.66 - 0.2) * m1 + (0.92 - 0.66) * m2;
  const h = (MBOT - MTOP) * f;
  const c = api.mixColor(api.mixColor(TEAL, ACC, m1), RED, m2);
  api.set(E.fill, {y: MBOT - h, height: h, fill: c});
  api.set(E.risk, {fill: api.mixColor(MUTED, RED, m2)});
}
